-- Migração 27 (cw_prod): IRPF 2026 como única regra em uso (fonte oficial RFB + Lei 15.270/2025). Cole no SQL Editor e execute.
begin;
-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 18: IRPF 2026 is the only rule set in use (D-053). Additive; published rule sets stay immutable (BR-9.4).
-- Official source: RFB, tabelas do IRPF 2026 (https://www.gov.br/receitafederal/pt-br/assuntos/meu-imposto-de-renda/tabelas/2026)
-- and Lei 15.270/2025 art. 11-A (annual reducer: up to R$ 2.694,15 until R$ 60.000; R$ 8.429,73 − 0,095575 × income until R$ 88.200).
-- The 2026 values already seeded (monthly table × 12; reducer) were checked against those sources on 15/10/2026.

-- An environment where the 2026 rule set is still an unpublished draft (non-production) gets it published, so
-- homologation computes exactly like production. No-op where a 2026 version is already published.
update cw_prod.tax_rule_sets r
   set published_at = now(),
       source_reference = 'RFB, Tabelas IRPF 2026 (gov.br/receitafederal … /meu-imposto-de-renda/tabelas/2026): tabela mensal × 12, Lei 15.270/2025 art. 11-A (redução anual).'
 where r.tax = 'IRPF' and r.tax_year = 2026 and r.published_at is null
   and not exists (select 1 from cw_prod.tax_rule_sets p where p.tax = r.tax and p.tax_year = 2026 and p.published_at is not null)
   and r.version = (select max(version) from cw_prod.tax_rule_sets d where d.tax = r.tax and d.tax_year = 2026);

-- Drafts other than 2026 that were never published and never used are removed (there are none today; kept for safety).
alter table cw_prod.tax_rule_sets disable trigger t_rule_set_guard;
delete from cw_prod.tax_rule_sets r
 where r.tax_year <> 2026 and r.published_at is null
   and not exists (select 1 from cw_prod.pgbl_calculations c where c.rule_set_id = r.id);
alter table cw_prod.tax_rule_sets enable trigger t_rule_set_guard;
commit;
select 'migração 27 ok' as resultado, (select count(*) from cw_prod.tax_rule_sets where tax_year = 2026 and published_at is not null) as regras_2026_publicadas, (select count(*) from cw_prod.tax_rule_sets where tax_year <> 2026) as outros_anos;
